/** CloudEvents 1.0 structured envelope with the Pulse extensions (appendix B). */
export interface Envelope<T extends EventType = EventType> {
  specversion: "1.0";
  id: string;
  source: string;
  type: T;
  time: string;
  subject: string;
  orgid: string;
  purpose: string;
  sensitivity: 0 | 1 | 2;
  visibility: "person" | "team" | "org";
  data: EventData[T];
  actor?: string;
  actorkind?: "person" | "account" | "device" | "system" | "ai" | "external";
  causationid?: string;
  collectorver?: string;
  confidence?: number;
  consentref?: string;
  correlationid?: string;
  datacontenttype?: "application/json";
  dataschema?: string;
  project?: string;
  supersedes?: string;
}
